/// One step of a sequence over a 32-bit value.
#[derive(Clone, Copy, Debug)]
enum Step32 {
    Get,
    Set(i32),
    Inc,
    Dec,
    Add(i32),
}

/// The edge values every sequence starts from.
const STARTS32: [i32; 7] = [0, 1, -1, i32::MAX, i32::MIN, i32::MAX - 1, i32::MIN + 1];

