    Step32::Get,
    Step32::Inc,
    Step32::Dec,
    Step32::Dec,
    Step32::Add(0),
    Step32::Add(i32::MAX),
    Step32::Add(i32::MIN),
    Step32::Set(i32::MAX),
    Step32::Inc,
    Step32::Dec,
    Step32::Set(i32::MIN),
    Step32::Dec,
    Step32::Add(-2),
    Step32::Add(3),
    Step32::Set(0),
    Step32::Get,
];

/// What a step returns on the Rust side: `set` returns nothing, as C's does.
fn rust_step32(v: Atomic32Ref<'_>, step: Step32) -> Option<i32> {
    match step {
        Step32::Get => Some(v.get()),
        Step32::Set(val) => {
            v.set(val);
            None
        }
        Step32::Inc => Some(v.inc()),
        Step32::Dec => Some(v.dec()),
        Step32::Add(addend) => Some(v.add(addend)),
    }
